import socket, struct, time, sys

HOST = "172.20.0.2"; PORT = 2404

class Client104:
    def __init__(self, host=HOST, port=PORT, timeout=5.0, verbose=True):
        self.s = socket.create_connection((host, port), timeout=timeout)
        self.s.settimeout(timeout)
        self.verbose = verbose
        self.rx_seq = 0
        self.tx_seq = 0
        self.msgs = []

    def _send(self, ctrl, payload=b""):
        apdu = ctrl + payload
        frame = bytes([0x68, len(apdu)]) + apdu
        self.s.sendall(frame)
        if self.verbose:
            print("TX|", frame.hex())

    def i_send(self, asdu: bytes):
        # I format: ctrl = seq low, seq high(=seq>>8 &0x7f... actually 15-bit seq)
        ctrl = struct.pack("<H", (self.tx_seq << 1)) + struct.pack("<H", (self.rx_seq << 1))
        self._send(ctrl, asdu)
        self.tx_seq = (self.tx_seq + 1) % 32768

    def s_send(self):
        ctrl = b"\x01" + b"\x00" + struct.pack("<H", (self.rx_seq << 1))
        self._send(ctrl)

    def startdt(self):
        self._send(b"\x07\x00\x00\x00")
    def stopdt(self):
        self._send(b"\x13\x00\x00\x00")
    def testfr(self):
        self._send(b"\x43\x00\x00\x00")

    def recv_frame(self, timeout=None):
        if timeout is not None:
            self.s.settimeout(timeout)
        try:
            hdr = b""
            while len(hdr) < 2:
                b1 = self.s.recv(1)
                if not b1:
                    return None
                if b1 == b"\x68":
                    hdr = b1
                    break
            ln = self.s.recv(1)
            if not ln:
                return None
            n = ln[0]
            data = b""
            while len(data) < n:
                chunk = self.s.recv(n - len(data))
                if not chunk:
                    return None
                data += chunk
            frame = b"\x68" + ln + data
            if self.verbose:
                print("RX|", frame.hex())
            return frame
        except socket.timeout:
            return None

    def drain(self, idle=1.0, max_frames=200):
        out = []
        while True:
            f = self.recv_frame(timeout=idle)
            if f is None:
                break
            out.append(f)
            if len(out) >= max_frames:
                break
            # short idle after first
            self.s.settimeout(0.4)
        self.s.settimeout(5.0)
        return out

    def parse_apci(self, frame):
        ctrl = frame[2:6]
        c1 = ctrl[0]
        fmt = ("I" if (c1 & 0x01) == 0 else ("S" if (c1 & 0x02) == 0 else "U"))
        rx = tx = None
        if fmt == "I":
            tx = struct.unpack("<H", ctrl[0:2])[0] >> 1
            rx = struct.unpack("<H", ctrl[2:4])[0] >> 1
            self.rx_seq = (rx + 1) % 32768
        elif fmt == "S":
            rx = struct.unpack("<H", ctrl[2:4])[0] >> 1
        payload = frame[6:] if fmt == "I" else b""
        return fmt, tx, rx, payload

def explain_asdu(asdu: bytes):
    if len(asdu) < 6:
        return None
    t = asdu[0]; sq = asdu[1] & 0x80; n = asdu[1] & 0x7f
    cot = asdu[2]; pn = (asdu[2+0],)  # will compute below properly
    # ASDU: type, vsq, cot, oa, ca(2), then info
    typ = asdu[0]; vsq = asdu[1]; cot = asdu[2]; oa = asdu[3]
    ca = asdu[4] | (asdu[5] << 8)
    info = asdu[6:]
    return dict(type=typ, sq=bool(vsq & 0x80), n=vsq & 0x7f, cot=cot, oa=oa, ca=ca, info=info.hex())
